from pysat.solvers import Cadical153, Glucose3, Minisat22
from pysat.card import CardEnc, EncType
from pysat.formula import IDPool
G=6; K=3; n=18; M=33
idx=lambda g,i:3*g+i
edges=[]
for g in range(G):
 for i in range(K):
  for j in range(i+1,K): edges.append((idx(g,i),idx(g,j)))
for g in range(G-1):
 for i in range(K): edges.append((idx(g,i),idx(g+1,i)))
print('edges',len(edges))
vpool=IDPool()
def X(v,l): return vpool.id(('x',v,l))
def Y(e,d): return vpool.id(('y',e,d))
clauses=[]
# vertex exactly one
for v in range(n):
 lits=[X(v,l) for l in range(M+1)]
 clauses.append(lits)
 for i in range(len(lits)):
  for j in range(i+1,len(lits)):
   clauses.append([-lits[i],-lits[j]])
# label at most one vertex
for l in range(M+1):
 lits=[X(v,l) for v in range(n)]
 for i in range(n):
  for j in range(i+1,n): clauses.append([-lits[i],-lits[j]])
# y at most one per edge
for e in range(len(edges)):
 lits=[Y(e,d) for d in range(1,M+1)]
 for i in range(len(lits)):
  for j in range(i+1,len(lits)):
   clauses.append([-lits[i],-lits[j]])
# each diff at most one edge
for d in range(1,M+1):
 lits=[Y(e,d) for e in range(len(edges))]
 for i in range(len(lits)):
  for j in range(i+1,len(lits)):
   clauses.append([-lits[i],-lits[j]])
# implications label pair -> y
for e,(a,b) in enumerate(edges):
 for p in range(M+1):
  for q in range(M+1):
   if p==q: continue
   clauses.append([-X(a,p), -X(b,q), Y(e,abs(p-q))])
# symmetry: sort first clique x0<x1<x2, encode forbid x0>=x1 etc
for p in range(M+1):
 for q in range(p+1): # q <= p: not x0=p and x1=q
  clauses.append([-X(0,p), -X(1,q)])
for p in range(M+1):
 for q in range(p+1):
  clauses.append([-X(1,p), -X(2,q)])
# complement symmetry after sorted: enforce x0+x2 <=33? Either original or complement sorted has sum=33? if > complement gives <. Add <=33.
for p in range(M+1):
 for q in range(M+1):
  if p+q>33:
   clauses.append([-X(0,p), -X(2,q)])
print('vars',vpool.top,'clauses',len(clauses))
for Solver in [Cadical153, Glucose3, Minisat22]:
 print('trying',Solver)
 with Solver(bootstrap_with=clauses) as s:
  sat=s.solve_limited(expect_interrupt=True) if False else s.solve()
  print('sat?',sat)
  if sat:
   m=set(s.get_model())
   sol=[]
   for v in range(n):
    lab=[l for l in range(M+1) if X(v,l) in m]
    sol.append(lab[0] if lab else None)
   print(sol)
   diffs=[abs(sol[a]-sol[b]) for a,b in edges]
   print(len(set(diffs)), sorted(diffs), diffs)
   raise SystemExit
